<div class="container-fluid py-3"><div class="card"><div class="card-header"><h5 class="mb-0">{{ $return?'Edit':'Tambah' }} {{ $title_menu }}</h5></div><div class="card-body p-3 border-bottom"><div class="nav-wrapper"><a class="btn btn-secondary mb-0" href="{{ url($url_menu) }}"><i class="fas fa-circle-left me-1"></i><span class="font-weight-bold">Kembali</span></a><button class="btn btn-primary mb-0" form="trretp-form" type="submit"><i class="fas fa-floppy-disk me-1"></i><span class="font-weight-bold">Simpan</span></button></div></div><form action="{{ $action }}" id="trretp-form" method="POST"><div class="card-body">@csrf @if($method!=='POST')@method($method)@endif <div class="row g-3"><div class="col-md-4"><label>Nomor</label><input class="form-control" name="nomor_retur" required value="{{ old('nomor_retur',$return?->nomor_retur) }}"></div><div class="col-md-4"><label>Tanggal</label><input class="form-control" type="date" name="tanggal_retur" required value="{{ old('tanggal_retur',$return?->tanggal_retur?->format('Y-m-d')??now()->toDateString()) }}"></div><div class="col-md-4"><label>Sumber Retur</label><select class="form-select" name="sumber_retur" id="source"><option value="faktur" @selected(old('sumber_retur',$return?->sumber_retur)==='faktur')>Faktur</option><option value="penerimaan_barang" @selected(old('sumber_retur',$return?->sumber_retur)==='penerimaan_barang')>Penerimaan Barang</option></select></div><div class="col-md-6"><label>Pemasok</label><select class="form-select" name="pemasok_id" required><option></option>@foreach($suppliers as $supplier)<option value="{{ $supplier->id }}" @selected(old('pemasok_id',$return?->pemasok_id)==$supplier->id)>{{ $supplier->nama }}</option>@endforeach</select></div><div class="col-md-6"><label>Dokumen Sumber</label><select class="form-select" id="document"></select><input type="hidden" name="faktur_pembelian_id" id="invoice"><input type="hidden" name="penerimaan_barang_id" id="receipt"></div><div class="col-md-12"><label>Keterangan</label><textarea class="form-control" name="keterangan">{{ old('keterangan',$return?->keterangan) }}</textarea></div></div><hr><button class="btn btn-secondary btn-sm" type="button" id="add-item">Tambah Barang</button><table class="table"><thead><tr><th>Barang</th><th>Qty</th><th>Harga</th><th></th></tr></thead><tbody id="items"></tbody></table></div></form></div></div>
@push('js')<script>const goods=@json($goods),invoices=@json($invoices),receipts=@json($receipts),items=@json(old('items',$items));let n=0;function docs(){let list=$('#source').val()==='faktur'?invoices:receipts;$('#document').html('<option></option>'+list.map(x=>`<option value="${x.id}">${x.nomor_form}</option>`).join(''));let current=$('#source').val()==='faktur'?{{ $return?->faktur_pembelian_id??'null' }}:{{ $return?->penerimaan_barang_id??'null' }};if(current)$('#document').val(current);sync()}function sync(){$('#invoice').val($('#source').val()==='faktur'?$('#document').val():'');$('#receipt').val($('#source').val()==='penerimaan_barang'?$('#document').val():'')}function row(i={}){let k=n++;$('#items').append(`<tr><td><select class="form-select" name="items[${k}][barang_jasa_kode]" required><option></option>${goods.map(x=>`<option value="${x.kode_barang}" ${x.kode_barang===i.barang_jasa_kode?'selected':''}>${x.kode_barang} - ${x.nama_barang}</option>`).join('')}</select></td><td><input class="form-control" type="number" min="0.0001" step="0.0001" name="items[${k}][kuantitas]" value="${i.kuantitas??1}" required></td><td><input class="form-control" type="number" min="0" step="0.01" name="items[${k}][harga_satuan]" value="${i.harga_satuan??0}"></td><td><button type="button" class="btn btn-danger btn-sm remove" aria-label="Hapus baris"><i class="fas fa-trash"></i></button></td></tr>`)}$(function(){docs();(items.length?items:[{}]).forEach(row);$('#source').change(docs);$('#document').change(sync);$('#add-item').click(()=>row());$('#items').on('click','.remove',function(){$(this).closest('tr').remove()})})</script>@endpush
